def minRowSweepDescent(matrix):
    n = len(matrix[0])
    f = [0] * n
    for row in matrix:
        P = [0] * (n + 1)
        for i in range(n):
            P[i + 1] = P[i] + row[i]
        new = [0] * n
        run = float("inf")
        for b in range(n):
            run = min(run, f[b] - P[b])
            new[b] = run + P[b + 1]
        run = float("inf")
        for b in range(n - 1, -1, -1):
            run = min(run, f[b] + P[b + 1])
            new[b] = min(new[b], run - P[b])
        f = new
    return min(f)
